begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into businesses(id,name,slug,timezone) values ('71000000-0000-0000-0000-000000000001','Confirm test','confirm-test','UTC');
insert into employees(id,business_id,name) values ('73000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','Professional');
insert into services(id,business_id,name,duration_minutes,price_cents) values ('74000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','Consultation',30,2500);
insert into employee_services(business_id,employee_id,service_id) values ('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001');
insert into employee_working_hours(business_id,employee_id,weekday,start_minute,end_minute)
select '71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001',d,540,720 from generate_series(1,7) d;
select is((select public_booking_enabled from businesses where id='71000000-0000-0000-0000-000000000001'),false,'Existing businesses stay closed');
set local role anon;
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z','76000000-0000-0000-0000-000000000001',' Client ',' Client@Example.test ',' ')$$,'42501','Booking unavailable','Closed business rejected');
reset role;
update businesses set public_booking_enabled=true where id='71000000-0000-0000-0000-000000000001';
set local role anon;
select lives_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z','76000000-0000-0000-0000-000000000001',' Client ',' Client@Example.test ',' ')$$,'Anon can confirm explicitly published business');
select lives_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z','76000000-0000-0000-0000-000000000001',' Client ',' Client@Example.test ',' ')$$,'Same normalized request replays');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z','76000000-0000-0000-0000-000000000001','Different',' Client@Example.test ',' ')$$,'22023','Request key already used','Changed payload cannot reuse key');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'23P01',null,'Occupied slot conflicts');
select lives_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:30Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'Adjacent slot accepted');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:07Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'23P01','Slot unavailable','Off-grid start rejected');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 11:45Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'23P01','Slot unavailable','Service must fit shift');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2000-01-05 10:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'23P01','Slot unavailable','Past slot rejected');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','infinity',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'22023','Invalid booking request','Infinite date rejected');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',null,' Client ',' Client@Example.test ',' ')$$,'22023','Invalid booking request','Missing request key rejected');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),' ',' Client@Example.test ',' ')$$,'22023','Invalid booking request','Empty name rejected');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),'Client','bad-email',' ')$$,'22023','Invalid booking request','Invalid email rejected');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000002','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),'Client','client@example.test',' ')$$,'42501','Booking unavailable','Unknown employee rejected');
select throws_ok($$select * from customers$$,'42501',null,'Anon cannot read customers');
select throws_ok($$select private.strict_local_instant('2099-01-05 10:00','UTC')$$,'42501',null,'Private helper inaccessible');
reset role;
select is((select count(*) from bookings where business_id='71000000-0000-0000-0000-000000000001'),2::bigint,'Exactly two bookings after retries and conflicts');
select is((select count(*) from customers where business_id='71000000-0000-0000-0000-000000000001'),2::bigint,'No orphan customers after failure');
select is((select email from customers where business_id='71000000-0000-0000-0000-000000000001' limit 1),'client@example.test','Email normalized');
select is((select name from customers where business_id='71000000-0000-0000-0000-000000000001' limit 1),'Client','Name trimmed');
select ok((select phone is null from customers where business_id='71000000-0000-0000-0000-000000000001' limit 1),'Empty phone becomes null');
select is((select price_cents from bookings where request_id='76000000-0000-0000-0000-000000000001'),2500,'Price computed by server');
select is((select ends_at from bookings where request_id='76000000-0000-0000-0000-000000000001'),'2099-01-05 09:30Z'::timestamptz,'End computed by server');
update services set price_cents=9999,name='Changed',is_active=false where id='74000000-0000-0000-0000-000000000001';
update businesses set public_booking_enabled=false where id='71000000-0000-0000-0000-000000000001';
set local role anon;
select is((public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z','76000000-0000-0000-0000-000000000001',' Client ',' Client@Example.test ',' ')->>'price_cents')::integer,2500,'Replay preserves committed snapshot after catalog changes and closure');
select ok(not (public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 09:00Z','76000000-0000-0000-0000-000000000001',' Client ',' Client@Example.test ',' ') ?| array['customer_id','email','phone','request_fingerprint']),'Receipt omits private contact data');
reset role;
update businesses set public_booking_enabled=true where id='71000000-0000-0000-0000-000000000001';
set local role anon;
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'42501','Booking unavailable','Inactive service rejected');
reset role;
update services set is_active=true where id='74000000-0000-0000-0000-000000000001';
update employees set is_active=false where id='73000000-0000-0000-0000-000000000001';
set local role anon;
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'42501','Booking unavailable','Inactive employee rejected');
reset role;
update employees set is_active=true where id='73000000-0000-0000-0000-000000000001';
delete from employee_services where employee_id='73000000-0000-0000-0000-000000000001';
set local role anon;
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'42501','Booking unavailable','Unassigned service rejected');
reset role;
insert into employee_services(business_id,employee_id,service_id) values ('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001');
insert into employee_blocked_periods(business_id,employee_id,starts_at,ends_at) values ('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001','2099-01-05 10:15Z','2099-01-05 10:45Z');
set local role anon;
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-05 10:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'23P01','Slot unavailable','Partial block overlap rejected');
reset role;
-- Horários adjacentes, noite contínua e DST.
delete from employee_working_hours where employee_id='73000000-0000-0000-0000-000000000001';
insert into employee_working_hours(business_id,employee_id,weekday,start_minute,end_minute)
select '71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001',d,x,y from generate_series(1,7) d cross join (values (0,60),(1380,1410),(1410,1440)) p(x,y);
update services set duration_minutes=90 where id='74000000-0000-0000-0000-000000000001';
set local role anon;
select lives_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-06 23:30Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'Adjacent local periods and midnight continuity accepted');
select throws_ok($$select public.confirm_booking('confirm-test','73000000-0000-0000-0000-000000000001','74000000-0000-0000-0000-000000000001','2099-01-07 00:00Z',gen_random_uuid(),' Client ',' Client@Example.test ',' ')$$,'23P01','Slot unavailable','Gap after midnight cannot be crossed');
reset role;
select throws_ok($$select private.strict_local_instant('2026-03-29 01:30','Europe/Lisbon')$$,'22023','Invalid working hours boundary','DST gap rejected');
select throws_ok($$select private.strict_local_instant('2026-10-25 01:30','Europe/Lisbon')$$,'22023','Ambiguous working hours boundary','DST repeated boundary rejected');
select is(private.strict_local_instant('2026-10-25 02:00','Europe/Lisbon'),'2026-10-25 02:00Z'::timestamptz,'Unique DST boundary accepted');
delete from employee_working_hours where employee_id='73000000-0000-0000-0000-000000000001';
insert into employee_working_hours(business_id,employee_id,weekday,start_minute,end_minute) values
  ('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001',5,0,1440),
  ('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001',6,0,1440),
  ('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001',7,0,90);
select lives_ok($$select private.booking_working_periods('71000000-0000-0000-0000-000000000001','73000000-0000-0000-0000-000000000001','2026-03-27','Europe/Lisbon',30)$$,'Unrelated future DST boundary does not invalidate available day');
select * from finish();
rollback;
